"""Generate Kotlin domain constants from the single public offer contract."""
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
contract = json.loads((ROOT/'android/app/src/main/assets/offer-contract.json').read_text())
wire = json.dumps(contract, ensure_ascii=False, separators=(',', ':'))
literal = json.dumps(wire, ensure_ascii=False).replace('$', '\\$')
kotlin = '''package at.hausgarten.service

import org.json.JSONObject

/** GENERATED by tools/sync_offer_contract.py; edit offer-contract.json only. */
internal object OfferContract {
    @JvmStatic
    @Throws(Exception::class)
    fun data(): JSONObject = JSONObject(%s)

    @JvmStatic
    fun values(key: String): Array<String> = try {
        val rows = data().getJSONArray(key)
        Array(rows.length()) { rows.getString(it) }
    } catch (failure: Exception) {
        throw IllegalStateException("Dokumentvertrag fehlt.")
    }

    @JvmStatic
    fun type(id: String): JSONObject = try {
        val rows = data().getJSONArray("document_types")
        (0 until rows.length()).map { rows.getJSONObject(it) }.firstOrNull { it.getString("id") == id } ?: JSONObject()
    } catch (failure: Exception) {
        throw IllegalStateException(failure)
    }

    @JvmStatic
    fun types(): Array<String> = try {
        val rows = data().getJSONArray("document_types")
        Array(rows.length()) { rows.getJSONObject(it).getString("id") }
    } catch (failure: Exception) {
        throw IllegalStateException(failure)
    }
}
''' % literal
path = ROOT/'android/app/src/main/java/at/hausgarten/service/OfferContract.kt'
if '--write' in sys.argv:
    path.write_text(kotlin)
elif not path.is_file() or path.read_text() != kotlin:
    raise SystemExit('Stale generated Kotlin offer contract: '+str(path.relative_to(ROOT)))
print('PASS shared Kotlin offer contract')
